<script setup lang="ts">
import { ref,computed,onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { post } from '../api'
import { state,speak } from '../store'
import Icon from '../components/Icon.vue'
import AnnotationCanvas from '../components/AnnotationCanvas.vue'
import QuestionInput from '../components/QuestionInput.vue'
const router=useRouter(),step=ref(0),run=ref<any>(),error=ref(''),busy=ref(false),goal=ref('岗位入门'),daily=ref(10),answer=ref<any>({}),guided=ref<any>({}),found=ref(false),feedback=ref<any>(),diagnosticIndex=ref(0),diagnosticAnswer=ref<any>({})
const stages=['欢迎','认识标注','设定目标','找到目标','学习框选','学习标签','独立完成','即时反馈','学情诊断','开始成长']
const current= computed(()=>run.value?.questions[step.value<=5?0:1])
onMounted(async()=>{try{run.value=await post('/onboarding/start')}catch(e){error.value=(e as Error).message}})
function next(){error.value='';step.value++;if(step.value===1)speak('数据标注，就是把你看懂的东西，告诉人工智能。');if(step.value===6)speak('这一次，换你独立来试试。不用担心，我们可以多次练习。')}
function spot(p:number[]){const b=current.value.guide_box;found.value=p[0]>=b[0]&&p[0]<=b[0]+b[2]&&p[1]>=b[1]&&p[1]<=b[1]+b[3];if(found.value){error.value='';speak('找到啦！你已经完成了第一步。')}else error.value='再观察一下，试着点击任务指定的目标。'}
async function submitGuide(){busy.value=true;error.value='';try{const r=await post(`/runs/${run.value.id}/answer`,{question_id:run.value.questions[0].id,answer:guided.value});if(r.result.correct){next();speak('做得很好！你已经学会框出目标并选择标签。')}else error.value='标签或边界还可以更准确。返回上一步调整边界，再选中目标标签。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function submitIndependent(){busy.value=true;error.value='';try{const r=await post(`/runs/${run.value.id}/answer`,{question_id:current.value.id,answer:answer.value});feedback.value=r.result;step.value=7;speak(r.result.correct?'太棒了，你完成了第一枚独立标注！':'位置已经有了，再调整一下边界和标签，我们继续试试。')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function submitDiagnostic(){busy.value=true;error.value='';try{await post(`/runs/${run.value.id}/answer`,{question_id:run.value.questions[diagnosticIndex.value+2].id,answer:diagnosticAnswer.value});diagnosticAnswer.value={};if(diagnosticIndex.value<2)diagnosticIndex.value++;else step.value=9}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function finish(){busy.value=true;try{state.user=await post('/onboarding/complete',{run_id:run.value.id,goal:goal.value,daily_goal:daily.value});router.push('/')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const hasBox=computed(()=>guided.value?.boxes?.some((b:any)=>b.box[2]>.02&&b.box[3]>.02));const hasLabel=computed(()=>hasBox.value&&guided.value.boxes.every((b:any)=>b.label))
</script>
<template><div class="onboarding-page"><header class="learning-header"><a href="/" class="brand"><img src="/favicon.svg" alt=""><span>智基<span class="brand-dot">.</span></span></a><div class="onboarding-progress"><div class="progress-line"><span :style="{width:((step+1)/10*100)+'%'}"></span></div><span>{{step+1}} / 10</span></div><button class="icon-button" @click="state.user!.voice=!state.user!.voice" :aria-label="state.user?.voice?'关闭语音':'开启语音'"><Icon :name="state.user?.voice?'Volume2':'VolumeX'"/></button></header><div v-if="!run" class="loading-state"><span v-if="error">{{error}}</span><template v-else><Icon name="LoaderCircle" class="spin"/>准备你的第一次标注体验…</template></div><div v-else class="onboarding-body" :class="{wide:step>=3&&step<=6}" :key="step"><span class="onboarding-step">{{stages[step]}}</span><template v-if="step===0"><img src="/mentor.png" class="welcome-mentor" alt="挥手的小基"><h1>嗨，我是小基。<br>一起教会 AI 看懂世界吧！</h1><p>不需要任何基础。跟着我动手试一试，<br>几分钟后，你就能完成自己的第一枚标注。</p><div class="onboarding-tags"><span><Icon name="MousePointer2" :size="17"/>边做边学</span><span><Icon name="MessageCircle" :size="17"/>即时反馈</span><span><Icon name="RotateCcw" :size="17"/>放心尝试</span></div></template><template v-if="step===1"><div class="concept-flow"><span><Icon name="ScanEye" :size="44"/>你看见目标</span><Icon name="ArrowRight" :size="25"/><span class="focus"><Icon name="SquareDashed" :size="44"/>为目标做标记</span><Icon name="ArrowRight" :size="25"/><span><Icon name="Sparkles" :size="44"/>AI 从中学习</span></div><h1>你看得懂，AI 还需要学习。</h1><p>当你告诉 AI “这里有一辆汽车”，<br>并把汽车的位置标出来，你就在做<strong>数据标注</strong>。</p><div class="concept-example">自动驾驶识别行人、工厂发现缺陷、客服理解文字，<br>背后都离不开清晰、准确的标注。</div></template><template v-if="step===2"><h1>你想从哪里开始？</h1><p>选一个最适合你的目标，后面也可以随时调整。</p><div class="goal-options"><button v-for="(g,i) in ['岗位入门','课程补强','竞赛备战']" :key="g" :class="{selected:goal===g}" @click="goal=g"><Icon :name="['BriefcaseBusiness','BookOpen','Trophy'][i]!" :size="27"/><span><b>{{g}}</b><small>{{['从零开始，掌握岗位基础','发现薄弱点，补齐关键技能','系统训练，迎接限时挑战'][i]}}</small></span><Icon v-if="goal===g" name="Check" :size="20"/></button></div><label class="daily-goal-label">每天留给成长一点时间</label><div class="time-options"><button v-for="n in [5,10,20]" :key="n" :class="{selected:daily===n}" @click="daily=n">{{n}} 分钟</button></div></template><template v-if="step===3"><h1>先找到它，不急着画框。</h1><p>在图片中，点击<strong>最大的{{current.guide_label}}</strong>。<br>标注的第一步，是先看清目标。</p><AnnotationCanvas :question="current" :model-value="{}" find-only @spot="spot"/><div v-if="found" class="inline-success"><Icon name="Check"/>找到啦！现在我们知道该标哪里了。</div></template><template v-if="step===4"><h1>给目标，画一个刚刚好的框。</h1><p>从目标的左上角按住鼠标，拖到右下角再松开。<br>尽量贴合边缘，也别漏掉任何部分。</p><AnnotationCanvas :question="current" v-model="guided" guide :labels-visible="false"/></template><template v-if="step===5"><h1>这个目标，叫什么？</h1><p>框告诉 AI “在哪里”，标签告诉 AI “是什么”。<br>点选下面与目标对应的标签。</p><AnnotationCanvas :question="current" v-model="guided" guide/></template><template v-if="step===6"><h1>这一次，你来独立完成。</h1><p>{{current.title}}<br>看图片 → 找目标 → 标出来 → 选标签 → 提交。</p><AnnotationCanvas :question="current" v-model="answer"/></template><template v-if="step===7"><div class="feedback-symbol" :class="{retry:!feedback.correct}"><Icon :name="feedback.correct?'Check':'RotateCcw'" :size="50"/></div><h1>{{feedback.correct?'你的第一枚标注，完成了！':'再调整一点，就更好了。'}}</h1><p>{{feedback.correct?'从看见目标，到告诉 AI 它是什么，你已经掌握了完整流程。':feedback.feedback}}</p><div class="feedback-iou"><span>区域重合度</span><b>{{Math.round((feedback.iou||0)*100)}}<small>%</small></b><span>{{feedback.correct?'边界与标签都通过了检查':'对照目标边缘，检查框是否过大或过小'}}</span></div><div v-if="!feedback.correct" class="concept-example">每一次调整都在帮助你学会观察。<br>点击“再试一次”，用刚刚学到的方法改进标注。</div></template><template v-if="step===8"><span class="pill purple">诊断 {{diagnosticIndex+1}} / 3</span><h1>最后，看看你已经知道什么。</h1><p>这是起点，不是考试。我们会用它为你推荐下一步。</p><h2 class="diagnostic-title">{{run.questions[diagnosticIndex+2].title}}</h2><QuestionInput :key="diagnosticIndex" :question="run.questions[diagnosticIndex+2]" v-model="diagnosticAnswer"/></template><template v-if="step===9"><img src="/mentor.png" class="welcome-mentor small" alt="小基"><span class="pill lime"><Icon name="Check" :size="14"/>入门体验已完成</span><h1>准备好了，向真本领出发。</h1><p>你的目标是<strong>{{goal}}</strong>，每天<strong>{{daily}} 分钟</strong>。<br>接下来，从基础认知开始，逐步走向真实岗位。</p><div class="onboarding-tags"><span><Icon name="ScanLine"/>第一枚标注</span><span><Icon name="Target"/>个性化学习路径</span></div></template><div v-if="error" class="error-message" role="alert">{{error}}</div></div><footer v-if="run" class="learning-footer"><div><button v-if="step>0&&step<7" class="text-button" @click="step--;error='' "><Icon name="ArrowLeft" :size="16"/>上一步</button><span v-else class="footer-encouragement">每一个高手，都从第一次尝试开始。</span><button v-if="step<=4" class="btn green" @click="next" :disabled="step===3&&!found||step===4&&!hasBox">{{step===0?'好，开始吧':step===2?'就是这个目标':'继续'}}<Icon name="ArrowRight" :size="18"/></button><button v-if="step===5" class="btn green" @click="submitGuide" :disabled="busy||!hasLabel">检查我的标注<Icon name="Check" :size="18"/></button><button v-if="step===6" class="btn green" @click="submitIndependent" :disabled="busy||!answer.boxes?.length||!answer.boxes?.every((b:any)=>b.label)">提交标注<Icon name="Check" :size="18"/></button><button v-if="step===7" class="btn green" @click="feedback.correct?step=8:step=6">{{feedback.correct?'继续了解自己':'再试一次'}}<Icon name="ArrowRight" :size="18"/></button><button v-if="step===8" class="btn green" @click="submitDiagnostic" :disabled="busy||!diagnosticAnswer.value">{{diagnosticIndex<2?'下一题':'看看我的起点'}}<Icon name="ArrowRight" :size="18"/></button><button v-if="step===9" class="btn green" @click="finish" :disabled="busy">{{busy?'保存中…':'进入正式训练'}}<Icon name="ArrowRight" :size="18"/></button></div></footer></div></template>
